const raw = $input.first().json.content[0].text;
let parsed;
try { parsed = JSON.parse(raw); } catch (e) {
  const m = raw.match(/\{[\s\S]*\}/);
  if (!m) throw new Error('LLM did not return valid JSON: ' + raw.slice(0, 200));
  parsed = JSON.parse(m[0]);
}
const event = $node['Eventbrite Fetch'].json;
return [{ json: {
  caption: parsed.caption,
  hashtags: parsed.hashtags || [],
  recommended_channel: parsed.recommended_channel,
  event_id: event.id,
  event_title: event.name.text,
  event_url: event.url,
  event_start_local: event.start.local,
  event_venue: event.venue?.address?.localized_address_display || 'TBD',
  image_url: event.logo?.original?.url || event.logo?.url
} }];

const event_id = String($node["Parse LLM"].json.event_id);
const event_title = $node["Parse LLM"].json.event_title;
const event_start = $node["Parse LLM"].json.event_start_local;
const event_venue = $node["Parse LLM"].json.event_venue;
const event_url = $node["Parse LLM"].json.event_url;
const image_url = $node["Parse LLM"].json.image_url;
const caption = $node["Parse LLM"].json.caption;
const hashtags = ($node["Parse LLM"].json.hashtags || []).join(" ");
const recommended_channel = $node["Parse LLM"].json.recommended_channel;

const TOPIC_OPTIONS = [{"text": {"type": "plain_text", "text": "#transit-task-force"}, "value": "#transit-task-force"}, {"text": {"type": "plain_text", "text": "#level-up-chicago"}, "value": "#level-up-chicago"}, {"text": {"type": "plain_text", "text": "#do-the-math"}, "value": "#do-the-math"}, {"text": {"type": "plain_text", "text": "#just-bikes"}, "value": "#just-bikes"}];

const blocks = [
  { type: "header", text: { type: "plain_text", text: event_title.substring(0, 150) } },
  { type: "section", text: { type: "mrkdwn", text: `*When:* ${event_start}\n*Where:* ${event_venue}\n*Eventbrite:* <${event_url}|View event>` } }
];
if (image_url) {
  blocks.push({ type: "image", image_url, alt_text: "Event image" });
}
blocks.push(
  { type: "section", text: { type: "mrkdwn", text: `*Proposed caption:*\n${caption}\n\n${hashtags}` } },
  {
    type: "section",
    block_id: "channel_override_block",
    text: { type: "mrkdwn", text: `*Topic channel:* (LLM recommended: ${recommended_channel})` },
    accessory: {
      type: "static_select",
      action_id: "channel_override",
      placeholder: { type: "plain_text", text: "Override channel" },
      options: TOPIC_OPTIONS
    }
  },
  {
    type: "actions",
    block_id: "approval_actions",
    elements: [
      { type: "button", action_id: "approve", style: "primary", text: { type: "plain_text", text: "Approve" }, value: event_id },
      { type: "button", action_id: "edit",                       text: { type: "plain_text", text: "Edit" },    value: event_id }
    ]
  }
);

const fallbackText = `New STC event for approval: ${event_title} — ${event_start}`;

// Build payload for chat.postMessage
const payload = {
  channel: "C0B60JLNQ20",
  text: fallbackText,
  blocks: blocks
};

return [{ json: { payload, event_id, event_title, recommended_channel } }];

const crypto = require('crypto');
const headers = $input.first().json.headers;
const body = $input.first().json.body;

const ts = headers['x-slack-request-timestamp'];
const sig = headers['x-slack-signature'];
if (!ts || !sig) throw new Error('Missing Slack signature headers');
if (Math.abs(Date.now()/1000 - parseInt(ts)) > 60 * 5) throw new Error('Stale Slack request (replay protection)');

// Form-encoder matching application/x-www-form-urlencoded (what Slack signed)
function formEncode(s) {
  return encodeURIComponent(String(s))
    .replace(/%20/g, '+')
    .replace(/!/g, '%21')
    .replace(/'/g, '%27')
    .replace(/\(/g, '%28')
    .replace(/\)/g, '%29')
    .replace(/\*/g, '%2A')
    .replace(/~/g, '%7E');
}

// Reconstruct body. For Slack interactivity, body is { payload: <urlencoded-json> }
// Object.keys preserves insertion order in modern V8, same as Slack's form-encoded order.
let rawBody;
if (typeof body === 'string') {
  rawBody = body;
} else if (body && typeof body === 'object') {
  rawBody = Object.keys(body)
    .map(k => formEncode(k) + '=' + formEncode(body[k]))
    .join('&');
} else {
  throw new Error('Cannot determine raw body for signature verification');
}

const baseString = `v0:${ts}:${rawBody}`;
const expected = 'v0=' + crypto.createHmac('sha256', $env.SLACK_SIGNING_SECRET).update(baseString).digest('hex');

if (!crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(expected))) {
  throw new Error('Slack signature mismatch — request may be spoofed (computed=' + expected.slice(0,20) + '... vs sent=' + sig.slice(0,20) + '...)');
}
return $input.all();

const body = $input.first().json.body;
const payload = JSON.parse(body.payload);
return [{ json: {
  action_id: payload.actions[0].action_id,
  event_id: payload.actions[0].value,
  selected_channel: payload.state?.values?.channel_override_block?.channel_override?.selected_option?.value || null,
  approver_user: payload.user.id,
  approver_name: payload.user.name || payload.user.username,
  message_ts: payload.message.ts,
  message_channel: payload.channel.id,
  original_blocks: payload.message.blocks
} }];

const VALID_CHANNELS = ["#transit-task-force", "#level-up-chicago", "#do-the-math", "#just-bikes"];
const data = $input.first().json;
const blocks = data.original_blocks;

const headerBlock = blocks.find(b => b.type === 'header');
const event_title = headerBlock?.text?.text || '(untitled)';

const whenWhereBlock = blocks.find(b => b.type === 'section' && b.text?.text?.includes('Eventbrite:'));
const whenWhereText = whenWhereBlock?.text?.text || '';
const urlMatch = whenWhereText.match(/<(https?:\/\/[^|>]+)\|/);
const event_url = urlMatch ? urlMatch[1] : '';
const lines = whenWhereText.split('\n').filter(l => !l.startsWith('*Eventbrite:'));
const when_where = lines.join('\n');

const captionBlock = blocks.find(b => b.type === 'section' && b.text?.text?.startsWith('*Proposed caption:*'));
const caption_with_hashtags = captionBlock?.text?.text.replace(/^\*Proposed caption:\*\n/, '') || '';

const topicBlock = blocks.find(b => b.block_id === 'channel_override_block');
const topicText = topicBlock?.text?.text || '';
const recommendMatch = topicText.match(/LLM recommended:\s*(#[\w-]+)/);
const llm_recommended = recommendMatch ? recommendMatch[1] : null;

let final_topic_channel = null;
if (data.selected_channel && VALID_CHANNELS.includes(data.selected_channel)) {
  final_topic_channel = data.selected_channel;
} else if (llm_recommended && VALID_CHANNELS.includes(llm_recommended)) {
  final_topic_channel = llm_recommended;
}
const should_post_topic = final_topic_channel !== null;

return [{ json: {
  ...data,
  event_title, event_url, when_where, caption_with_hashtags,
  llm_recommended, chosen_channel: final_topic_channel, should_post_topic
} }];

const raw = $input.first().json.body;
const body = (typeof raw === 'string') ? JSON.parse(raw) : raw;
if (body && body.type === 'url_verification') {
  return [{ json: { isChallenge: true, challenge: body.challenge } }];
}
return [{ json: { isChallenge: false, body, headers: $input.first().json.headers } }];

// TODO: Re-enable signature verification.
//
// Why bypassed: Slack signs the raw HTTP body bytes. For Slack EVENTS (this workflow's
// trigger), the body is JSON with Content-Type: application/json. n8n's webhook v2 parses
// JSON into a JS object before our Code node runs. Reconstructing the original bytes via
// JSON.stringify(parsed) produces different bytes than Slack signed — differences in
// whitespace, unicode escaping, and number formatting between Slack's JSON serializer and
// V8's JSON.stringify mean we get signature mismatch every time.
//
// Fixes to try (one-time, then this code goes away):
//   1. Switch webhook config to binaryData: true. Body becomes raw binary; HMAC over raw,
//      then JSON.parse for downstream. Cleanest but requires reworking the webhook node and
//      downstream parsing.
//   2. Use n8n's $binary input (if available) to access raw body alongside parsed body.
//   3. Capture raw body via a Caddy header (configure Caddy to inject X-Original-Body).
//
// Security implication of bypass: anyone who knows /webhook/slack-events URL could fire
// fake events. BUT downstream Filter Reaction node enforces:
//   - reaction must be :white_check_mark:
//   - reaction must be in channel APPROVAL_CHANNEL_ID
//   - event type must be reaction_added
// So worst-case attack = bot reposts a thread message as IG stub + announcement.
// No money, no IG (since IG-publish itself is also stubbed), no destructive actions.
// Bounded acceptable for STC's threat model.
//
// The companion Action workflow (Slack interactivity) HAS working signature verification
// via a form-urlencoded encoder. That's the higher-stakes path (real button clicks).
return [{ json: $json }];

const evt = $json.body?.event;
if (!evt || evt.type !== 'reaction_added') return [];
if (evt.reaction !== 'white_check_mark') return [];
if (evt.item.channel !== $env.APPROVAL_CHANNEL_ID) return [];
return [{ json: {
  item_ts: evt.item.ts,
  channel: evt.item.channel,
  user: evt.user
} }];

const data = $input.first().json;
const replies = data.messages || [];
const itemTs = $node["Filter Reaction"].json.item_ts;
const userMsgs = replies.filter(m => !m.bot_id && m.ts !== itemTs);
const latest = userMsgs[userMsgs.length - 1];
if (!latest) throw new Error('No revised caption found in thread');
return [{ json: {
  caption_with_hashtags: latest.text,
  message_ts: itemTs,
  message_channel: $node["Filter Reaction"].json.channel,
  approver_user: $node["Filter Reaction"].json.user
} }];
